function bindContent(){$$('[data-open-match]').forEach(b=>b.onclick=()=>openSearchMatch(b.dataset.openMatch,Number(b.dataset.matchLine)));$$('[data-law-open]').forEach(b=>b.onclick=()=>openLawCatalog(b.dataset.lawOpen));$$('[data-open]').forEach(b=>b.onclick=()=>openDoc(b.dataset.open));$$('[data-save]').forEach(b=>b.onclick=()=>toggleSave(b.dataset.save));$$('[data-scope]').forEach(b=>b.onclick=showScope);$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));$$('[data-compare]').forEach(b=>b.onclick=()=>compareVersions(b.dataset.compare));$$('[data-shortcut]').forEach(b=>b.onclick=()=>{setDomain(b.dataset.shortcutDomain,false);$('#query').value=b.dataset.shortcut;state.page='home';search()});if($('#clearConditions'))$('#clearConditions').onclick=resetFilters}
async function toggleSave(id){let d=state.allDocuments.find(x=>x.id===id)||state.reader;const removing=saved(id);if(!removing){try{const fetched=await api('/api/documents/'+encodeURIComponent(id));d=fetched.document||fetched}catch(e){toast(e.message);return}}if(!removing&&!d)return;const bookmarks=removing?state.bookmarks.filter(x=>x.id!==id):[{id,savedAt:new Date().toISOString(),title:d.title,domain:d.domain,version:d.version||d.documentNumber||'버전 미확인',article:d.article||'',tag:'',note:'',snapshot:{...d}},...state.bookmarks];if(!storeLocal('lr-bookmarks-v1',bookmarks))return;state.bookmarks=bookmarks;toast(removing?'보관함에서 삭제했습니다.':'이 브라우저의 로컬 보관함에 저장했습니다.');$$(`[data-save="${CSS.escape(id)}"]`).forEach(b=>{b.classList.toggle('saved',saved(id));b.innerHTML=saved(id)?'◆':'◇';b.setAttribute('aria-label',saved(id)?'저장 해제':'자료 저장')});if(state.page==='library')renderLibrary()}
