 const updateMatches=(source='')=>{matches=$$('mark',body);matchIndex=-1;count.textContent=matches.length?(source?'검색어 ':'')+matches.length+'곳':input.value.trim()?'일치 없음':'';$('[data-find-prev]',root).disabled=!matches.length;$('[data-find-next]',root).disabled=!matches.length};
 const moveMatch=(delta)=>{clearTimeout(searchTimer);if(renderedTerm!==input.value)find();if(!matches.length)return;matches[matchIndex]?.classList.remove('current-match');matchIndex=matchIndex<0?(delta>0?0:matches.length-1):(matchIndex+delta+matches.length)%matches.length;const active=matches[matchIndex];active.classList.add('current-match');active.setAttribute('tabindex','-1');active.scrollIntoView({behavior:'smooth',block:'center'});active.focus({preventScroll:true});count.textContent=(matchIndex+1)+' / '+matches.length+'곳'};
 const find=()=>{if(!bodyAvailable(d)||renderedTerm===input.value)return;renderedTerm=input.value;body.innerHTML=readerBodyHtml(d,segments,input.value,true);updateMatches()};
 $$('[data-save]',root).forEach(b=>b.onclick=()=>toggleSave(b.dataset.save));$$('[data-open]',root).forEach(b=>b.onclick=()=>openDoc(b.dataset.open,root===$('#reader')));
 $('[data-reader-close]',root).onclick=()=>{clearTimeout(searchTimer);if(root===$('#reader'))$('#readerDialog').close();else{root.classList.add('hidden');$('#resultLayout')?.classList.remove('has-reader')}};
