async function init(){const now=new Date();$('#today').textContent=now.toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'long'});for(let y=now.getFullYear()+1;y>=2000;y--)$('#referenceYear').insertAdjacentHTML('beforeend',`<option value="${y}">${y}년</option>`);const url=new URLSearchParams(location.search);if(menus.some(x=>x[0]===url.get('page')))state.page=url.get('page');$('#query').value=url.get('q')||'';state.q=$('#query').value;if(/^\d{4}-\d{2}-\d{2}$/.test(url.get('date')||''))$('#referenceDate').value=url.get('date');setDomain(['tax','subcontract'].includes(url.get('domain'))?url.get('domain'):'all',false);$('#searchForm').onsubmit=e=>{e.preventDefault();if(state.page==='admin')return;search()};$$('[data-domain]').forEach(b=>b.onclick=()=>setDomain(b.dataset.domain));$$('[data-query]').forEach(b=>b.onclick=()=>{$('#query').value=b.dataset.query;search()});$('#advancedToggle').onclick=()=>{const open=$('#advanced').classList.toggle('hidden');$('#advancedToggle').setAttribute('aria-expanded',String(!open));$('#advancedToggle').innerHTML=`상세 조건 <span>${open?'＋':'−'}</span>`};$('#applyFilters').onclick=()=>search();$('#resetFilters').onclick=resetFilters;$('#referenceDate').onchange=()=>search();$('#referenceYear').onchange=()=>search();$('#scopeFooter').onclick=showScope;$('#localProfile').onclick=()=>navigate('library');$('#menuToggle').onclick=()=>setMenuOpen(!$('#sidebar').classList.contains('open'));window.addEventListener('resize',revealActiveNav);$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();$('#query').focus()}if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){setMenuOpen(false);$('#menuToggle').focus()}});document.addEventListener('click',e=>{if(innerWidth<=850&&$('#sidebar').classList.contains('open')&&!$('#sidebar').contains(e.target)&&!$('#menuToggle').contains(e.target))setMenuOpen(false)});heading();$('#content').innerHTML='<div class="loading">자료 수집 범위를 확인하고 있습니다.</div>';try{await refreshData();if(state.page==='admin')await renderAdmin();else if(state.page==='library')renderLibrary();else if(state.q||filtersActive()||state.page!=='home'){state.searched=Boolean(state.q);await search(false)}else renderHome()}catch(e){$('#topStatus').textContent='연결 오류';$('#content').innerHTML=`<div class="empty-state"><h3>앱 서버에 연결하지 못했습니다.</h3><p>${esc(e.message)} 실행 상태를 확인한 뒤 새로고침하세요.</p><button class="secondary" id="reloadApp">다시 시도</button></div>`;$('#reloadApp').onclick=()=>location.reload()}}
function lawConnectionPanel(){
 const u=state.updates||{},last=u.lastRun,schedule=u.schedule||{};
 const label={blocked:'연동 대기',failed:'갱신 실패','review-pending':'수집 완료 · 검토 대기','skipped-holiday':'공휴일 · 정기 갱신 건너뜀'}[last?.state]||'아직 실행하지 않음';
 const errors=(last?.errors||[]).map(e=>`${e.lawName}: ${e.message}`);
 return `<section class="admin-panel"><h2>법령 자동 갱신</h2><p><strong>월~금 오전 9시 · 한국시간(Asia/Seoul)</strong><br>국세 법령 6종·지방세 법령 4종과 각 시행령·시행규칙, 하도급법·시행령 등 32개를 확인합니다. 정기 실행은 하루 16개씩 번갈아 확인하고(이틀에 한 바퀴) 최근 30일 판례 목록도 함께 확인합니다. 새 버전은 검토 대기로 보관하고 공개하지 않습니다.</p><div class="notice ${schedule.excludesPublicHolidays?'':'warn'}">${schedule.excludesPublicHolidays?'공휴일 제외 적용 · 한국천문연구원 특일 정보 기준':'공휴일 제외 미적용 · 서버 환경 변수 HOLIDAY_API_KEY(공공데이터포털 특일 정보)를 등록하면 공휴일에는 정기 갱신을 건너뜁니다.'} <button type="button" class="text-button" id="checkHolidays">올해 공휴일 확인</button><div id="holidayList"></div></div><div class="library-info"><div><strong>${esc(label)}</strong><p>${esc(last?.reason||last?.message||'승인된 OC가 없으면 공식 API를 호출하지 않습니다.')}${errors.length?'<br>'+errors.slice(0,4).map(esc).join('<br>'):''}<br>마지막 실행 확인: ${date(last?.checkedAt)} · 법령 검토 대기 ${Number(u.lawReviewPending||0)}건</p></div></div><h3 class="section-title">OC 발급·등록 안내</h3><ol class="connection-steps"><li><a href="https://open.law.go.kr/" target="_blank" rel="noopener noreferrer">국가법령정보 공동활용 ↗</a>에서 회원가입 후 활용 신청을 진행하세요. 법령(현행·시행일)과 판례 서비스를 모두 신청하세요.</li><li>이용 조건과 신청 서비스 범위를 확인하고 승인된 OC 인증값을 확인하세요.</li><li>아래 입력란에 등록하세요. 인증값은 서버에 암호화하여 보관하며 화면에 다시 표시하지 않습니다.</li></ol><form id="lawConnectionForm"><label class="connection-label">승인된 OC 인증값<input id="lawApiOc" type="password" autocomplete="new-password" required placeholder="${u.credentialConfigured?'새 인증값으로 변경할 때만 입력':'승인된 OC 입력'}" maxlength="200"></label><label class="check-label connection-label"><input type="checkbox" required id="lawOcApproved">공동활용 승인과 이용 조건을 확인했습니다.</label><button class="primary" type="submit">${u.credentialConfigured?'연결 정보 변경':'서버에 등록'}</button>${u.credentialConfigured?'<button type="button" class="text-button danger" id="removeLawConnection">등록 정보 삭제</button>':''}</form><button class="secondary" id="runLawUpdate" type="button">지금 갱신 확인</button> <button class="text-button" id="forceLawUpdate" type="button" title="이미 앱에 있는 같은 버전도 공식 본문을 다시 받아 검토 대기에 올립니다">현재 버전 본문 다시 받기</button><div id="lawConnectionNotice" role="status"></div><details class="case-upload"><summary>운영 서버가 법제처에서 거절될 때 · 법령 파일 올리기</summary><p class="source-caption">법제처는 OC에 등록된 IP에서 온 요청만 받습니다. 내 PC에서 <code>npm run collect:laws</code>로 만든 <code>exports/laws-*.json</code> 파일을 선택하세요. 서버에서 실시간 수집과 같은 검증을 거쳐 검토 대기로만 올라갑니다.</p><input type="file" id="lawFile" accept=".json,application/json"><div id="lawFileNotice" role="status" aria-live="polite"></div></details><h3 class="section-title">법령 검토 대기</h3><div id="lawPending"><p class="source-caption">검토 목록을 불러오는 중입니다.</p></div></section>${caseConnectionPanel()}`;
}
const caseTrackNames={nts:'국세법령정보시스템 판례 (제목·링크)',court:'대법원 출처 세법·지방세 판례 (판결문)',subcontract:'하도급 관련 판례 (판결문)'};
function defaultCaseWindow(){const to=new Date(Date.now()+9*3600000).toISOString().slice(0,10),d=new Date(to+'T00:00:00Z');d.setUTCFullYear(d.getUTCFullYear()-2);d.setUTCDate(d.getUTCDate()+1);return {from:d.toISOString().slice(0,10),to}}
function caseConnectionPanel(){
 const c=state.updates?.cases,last=c?.lastRun,progress=c?.progress,win=progress?.window||defaultCaseWindow();
 const label={blocked:'연동 대기',failed:'수집 실패','review-pending':'수집 완료 · 검토 대기'}[last?.state]||'미연동 · 수집 전';
 const trackRows=Object.entries(caseTrackNames).map(([key,name])=>{const p=progress?.tracks?.[key];return `<label class="check-label"><input type="checkbox" data-case-track value="${key}" ${p?.done?'':'checked'}> ${esc(name)} <small class="source-caption">${p?(p.done?`완료 · 전체 ${Number(p.totalAvailable||0).toLocaleString('ko-KR')}건`:`${p.page}/${p.totalPages}페이지까지 수집`):'수집 전'}</small></label>`}).join('');
 return `<section class="admin-panel" style="margin-top:20px"><h2>판례 수집 · 최근 2년</h2><p>법제처 공동활용 판례 API로 선고일 기준 기간의 판례를 페이지 단위로 모두 가져와 <strong>검토 대기</strong>에 보관합니다. 국세법령정보시스템 판례는 공식 API가 본문을 제공하지 않아 사건명·사건번호·선고일·링크만 수록하고, 대법원 출처 세법·지방세·하도급 판례는 공식 판결문을 수록합니다.</p><div class="notice"><strong>${esc(label)}</strong><br>${esc(last?.reason||last?.message||'아직 공식 API 판례를 수집하지 않았습니다.')}<br>마지막 실행: ${date(last?.checkedAt)}${last?.track?` · ${esc(caseTrackNames[last.track]||last.track)} ${Number(last.page||0)}/${Number(last.totalPages||0)}페이지`:''}${last?.warningCount?` · 제외·확인 필요 ${Number(last.warningCount)}건`:''}</div><div class="case-window"><label class="connection-label">선고일 시작<input type="date" id="caseFrom" value="${esc(win.from)}"></label><label class="connection-label">선고일 종료<input type="date" id="caseTo" value="${esc(win.to)}"></label></div><div class="case-tracks">${trackRows}</div><div class="case-actions"><button class="primary" id="runCaseBackfill" type="button">${progress&&Object.values(progress.tracks||{}).some(t=>!t.done)?'이어서 수집':'수집 시작'}</button><button class="secondary hidden" id="stopCaseBackfill" type="button">멈춤</button></div><div id="caseUpdateNotice" class="case-progress" role="status" aria-live="polite"></div><details class="case-upload"><summary>서버가 law.go.kr에 연결하지 못할 때 · 수집 파일 올리기</summary><p class="source-caption">내 PC에서 <code>npm run collect:cases</code>로 만든 <code>exports/cases-*.json</code> 파일을 선택하세요. 파일 내용은 서버에서 수집기 형식과 다시 대조한 뒤 검토 대기로만 올라갑니다.</p><input type="file" id="caseFile" accept=".json,application/json"><div id="caseFileNotice" role="status"></div></details><h3 class="section-title">판례 검토 대기</h3><div id="casePending"><p class="source-caption">검토 목록을 불러오는 중입니다.</p></div></section>`;
}
async function loadLawPending(){
 const container=$('#lawPending');if(!container)return;
 try{
  const result=await api('/api/admin/laws/pending');if(!container.isConnected)return;
  container.innerHTML=result.laws.length?result.laws.map((x,i)=>`<div class="case-pending"><strong>${esc(x.lawName)}</strong><p>시행 ${date(x.effectiveDate&&x.effectiveDate.replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3'))} · 공포 ${date(x.promulgatedDate&&x.promulgatedDate.replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3'))} · 법령일련번호 ${esc(x.mst)}</p><label class="check-label"><input type="checkbox" id="lawReview-${i}"> 법령명·시행일·공포일과 부칙을 공식 원문과 대조했습니다.</label><button class="secondary" data-publish-law="${esc(x.id)}" data-law-index="${i}">전문 공개</button> <a class="text-button" href="${esc(safeUrl('https://www.law.go.kr/법령/'+encodeURIComponent(x.lawName)))}" target="_blank" rel="noopener noreferrer">공식 원문 ↗</a></div>`).join(''):'<p class="source-caption">검토 대기 중인 법령 수집본이 없습니다.</p>';
  $$('[data-publish-law]').forEach(button=>button.onclick=async()=>{if(!$('#lawReview-'+button.dataset.lawIndex).checked){toast('공식 원문과 먼저 대조하세요.');return}button.disabled=true;try{const r=await api('/api/admin/laws/publish',{method:'POST',body:JSON.stringify({id:button.dataset.publishLaw,reviewConfirmed:true})});toast(r.message);await refreshData();await loadLawPending()}catch(error){toast(error.message);button.disabled=false}});
 }catch(error){container.innerHTML=`<div class="notice warn">${esc(error.message)}</div>`}
}
const casePendingView={track:'',offset:0,limit:20};
async function loadCasePending(){
 const container=$('#casePending');if(!container)return;
 try{
  const v=casePendingView,p=new URLSearchParams({limit:String(v.limit),offset:String(v.offset)});if(v.track)p.set('track',v.track);
  const result=await api('/api/admin/cases/pending?'+p);if(!container.isConnected)return;
  const by=result.byTrack||{},scopeCount=v.track?Number(by[v.track]||0):Number(result.total);
  container.innerHTML=`<div class="guide-topic-bar" role="group" aria-label="검토 대기 범위"><button type="button" class="guide-topic ${!v.track?'active':''}" data-pending-track="" aria-pressed="${!v.track}">전체 <span>${Number(result.total).toLocaleString('ko-KR')}</span></button>${Object.entries(caseTrackNames).map(([key,name])=>`<button type="button" class="guide-topic ${v.track===key?'active':''}" data-pending-track="${key}" aria-pressed="${v.track===key}">${esc(name.split(' (')[0])} <span>${Number(by[key]||0).toLocaleString('ko-KR')}</span></button>`).join('')}</div>`+
  (scopeCount?`<div class="case-batch"><label class="check-label"><input type="checkbox" id="caseBatchConfirm"> 이 범위 ${scopeCount.toLocaleString('ko-KR')}건의 출처·본문 범위·이용 조건을 확인했고 공개합니다.</label><button class="primary" id="caseBatchPublish" type="button">이 범위 전체 공개</button> <button class="text-button danger" id="caseBatchDiscard" type="button">이 범위 전체 제외</button><div id="caseBatchNotice" role="status" aria-live="polite"></div></div>`:'')+
  `<p class="source-caption">${scopeCount?`${(v.offset+1).toLocaleString('ko-KR')}–${Math.min(v.offset+v.limit,scopeCount).toLocaleString('ko-KR')} / ${scopeCount.toLocaleString('ko-KR')}건 · 최근 수집 순`:'검토 대기 중인 판례가 없습니다.'}</p>`+
  (result.documents||[]).map((d,i)=>`<details class="case-pending"><summary><input type="checkbox" data-select-case="${esc(d.id)}" aria-label="선택"> ${esc(d.agency)} ${esc(d.documentNumber)} · ${esc(d.title)}</summary><p>${date(d.documentDate)} 선고 · ${bodyBadge(d)} ${(d.tags||[]).map(t=>`<span class="badge">${esc(t)}</span>`).join(' ')}</p><a href="${esc(safeUrl(d.sourceUrl))}" target="_blank" rel="noopener noreferrer">법제처 공식 원문 ↗</a><pre class="case-excerpt">${esc(d.body?d.body.slice(0,3000)+(d.body.length>3000?'\n…(검토 화면에서는 앞부분만 표시)':''):'본문 미확보 · 공식 원문에서 확인하세요.')}</pre><p class="source-caption">${esc(d.rights)}</p><label class="check-label"><input type="checkbox" id="caseReview-${i}"> 원문·발췌 범위·이용 조건을 검토했습니다.</label><button class="secondary" data-import-case="${esc(d.id)}" data-review-index="${i}">검토 후 공개 등록</button></details>`).join('')+
  (scopeCount>v.limit?`<div class="case-pager"><button class="secondary" id="casePrev" ${v.offset?'':'disabled'}>이전</button><button class="secondary" id="caseNext" ${v.offset+v.limit<scopeCount?'':'disabled'}>다음</button><button class="text-button" id="caseSelectedPublish">선택 공개</button><button class="text-button danger" id="caseSelectedDiscard">선택 제외</button></div>`:(result.documents||[]).length?`<div class="case-pager"><button class="text-button" id="caseSelectedPublish">선택 공개</button><button class="text-button danger" id="caseSelectedDiscard">선택 제외</button></div>`:'');
  $$('[data-pending-track]').forEach(b=>b.onclick=()=>{v.track=b.dataset.pendingTrack;v.offset=0;loadCasePending()});
  if($('#casePrev'))$('#casePrev').onclick=()=>{v.offset=Math.max(0,v.offset-v.limit);loadCasePending()};
  if($('#caseNext'))$('#caseNext').onclick=()=>{v.offset+=v.limit;loadCasePending()};
  $$('[data-select-case]').forEach(box=>box.onclick=e=>e.stopPropagation());
  const selected=()=>$$('[data-select-case]:checked').map(x=>x.dataset.selectCase);
  if($('#caseSelectedPublish'))$('#caseSelectedPublish').onclick=async()=>{const ids=selected();if(!ids.length){toast('공개할 판례를 선택하세요.');return}if(!confirm(`선택한 ${ids.length}건의 원문과 이용 조건을 확인했고 공개합니다.`))return;try{const r=await api('/api/admin/cases/import-batch',{method:'POST',body:JSON.stringify({ids,reviewConfirmed:true})});toast(r.message);await refreshData();loadCasePending()}catch(e){toast(e.message)}};
  if($('#caseSelectedDiscard'))$('#caseSelectedDiscard').onclick=async()=>{const ids=selected();if(!ids.length){toast('제외할 판례를 선택하세요.');return}try{const r=await api('/api/admin/cases/discard',{method:'POST',body:JSON.stringify({ids})});toast(r.message);loadCasePending()}catch(e){toast(e.message)}};
  if($('#caseBatchPublish'))$('#caseBatchPublish').onclick=async e=>{
   if(!$('#caseBatchConfirm').checked){toast('공개 전에 확인란을 선택하세요.');return}
   e.target.disabled=true;const notice=$('#caseBatchNotice');let imported=0,upgraded=0,duplicates=0;
   try{while(true){const r=await api('/api/admin/cases/import-batch',{method:'POST',body:JSON.stringify({...(v.track?{track:v.track}:{all:true}),reviewConfirmed:true,max:200})});imported+=r.imported||0;upgraded+=r.upgraded||0;duplicates+=r.duplicates||0;notice.textContent=`공개 ${imported.toLocaleString('ko-KR')}건 · 본문 보강 ${upgraded}건 · 중복 제외 ${duplicates}건 · 남은 검토 대기 ${Number(r.remaining).toLocaleString('ko-KR')}건`;if(!(r.imported||r.upgraded||r.duplicates||r.rejected))break}toast('공개를 마쳤습니다.');await refreshData();v.offset=0;loadCasePending()}catch(error){notice.textContent=error.message;e.target.disabled=false}
  };
  if($('#caseBatchDiscard'))$('#caseBatchDiscard').onclick=async()=>{if(!confirm(`이 범위 ${scopeCount.toLocaleString('ko-KR')}건을 공개하지 않고 검토 대기에서 제외합니다.`))return;try{const r=await api('/api/admin/cases/discard',{method:'POST',body:JSON.stringify(v.track?{track:v.track}:{all:true})});toast(r.message);v.offset=0;loadCasePending()}catch(e){toast(e.message)}};
  $$('[data-import-case]').forEach(button=>button.onclick=async()=>{if(!$('#caseReview-'+button.dataset.reviewIndex).checked){toast('원문과 이용 조건을 먼저 확인하세요.');return}button.disabled=true;try{const r=await api('/api/admin/cases/import',{method:'POST',body:JSON.stringify({id:button.dataset.importCase,reviewConfirmed:true})});toast(r.message);await refreshData();await loadCasePending()}catch(error){toast(error.message);button.disabled=false}});
 }catch(error){container.innerHTML=`<div class="notice warn">${esc(error.message)}</div>`}
}
async function runCaseBackfill(){
 const from=$('#caseFrom').value,to=$('#caseTo').value,tracks=$$('[data-case-track]:checked').map(x=>x.value),notice=$('#caseUpdateNotice');
 if(!from||!to||from>to){toast('선고일 범위를 확인하세요.');return}
 if(!tracks.length){toast('수집할 범위를 선택하세요.');return}
 const progress=state.updates?.cases?.progress,resume=progress?.window?.from===from&&progress?.window?.to===to;
 const run=state.caseRun={stop:false};$('#runCaseBackfill').disabled=true;$('#stopCaseBackfill').classList.remove('hidden');
 try{
  for(const track of tracks){
   const prior=resume?progress.tracks?.[track]:null;if(prior?.done)continue;
   let page=prior?prior.page+1:1;
   while(!run.stop){
    notice.textContent=`${caseTrackNames[track]} ${page}페이지 확인 중…`;
    const r=await api('/api/admin/updates/run',{method:'POST',body:JSON.stringify({dataset:'cases',track,from,to,page})});
    if(!r.ok){notice.textContent=`${caseTrackNames[track]} ${page}페이지 실패: ${r.reason||'알 수 없는 오류'} · 다시 누르면 이 페이지부터 이어서 수집합니다.`;run.stop=true;break}
    notice.textContent=`${caseTrackNames[track]} ${page}/${r.totalPages}페이지 · 이번 ${r.staged}건 검토 대기 추가${r.skippedExisting?` · 이미 공개 ${r.skippedExisting}건`:''} · 검토 대기 합계 ${Number(r.reviewPending).toLocaleString('ko-KR')}건`;
    if(r.done)break;page++;await new Promise(done=>setTimeout(done,300));
   }
   if(run.stop)break;
  }
  if(!run.stop)notice.textContent+=' · 선택한 범위 수집을 마쳤습니다. 아래 검토 대기에서 확인 후 공개하세요.';
 }catch(error){notice.textContent=error.message}
 state.updates=await api('/api/updates/status').catch(()=>state.updates);$('#runCaseBackfill').disabled=false;$('#stopCaseBackfill').classList.add('hidden');loadCasePending();
}
async function uploadLawFile(file){
 const notice=$('#lawFileNotice');
 try{
  const data=JSON.parse(await file.text());if(data.format!=='law-api-laws-v1'||!Array.isArray(data.laws))throw Error('collect-laws.mjs로 만든 파일이 아닙니다.');
  let done=0;const failed=[];
  for(const law of data.laws){notice.textContent=`${law.lawName} 올리는 중… (${done+failed.length+1}/${data.laws.length})`;try{await api('/api/admin/laws/stage',{method:'POST',body:JSON.stringify({format:data.format,law})});done++}catch(error){failed.push(law.lawName+': '+error.message)}}
  notice.innerHTML=`${done}종을 검토 대기로 올렸습니다.${failed.length?'<br>'+failed.map(esc).join('<br>'):''}`;toast('법령 파일을 검토 대기로 올렸습니다.');loadLawPending();
 }catch(error){notice.textContent=error.message}
}
async function uploadCaseFile(file){
 const notice=$('#caseFileNotice');
 try{
  const data=JSON.parse(await file.text());if(data.format!=='law-api-cases-v1'||!Array.isArray(data.documents))throw Error('collect-cases.mjs로 만든 파일이 아닙니다.');
  let staged=0,rejected=0,skipped=0,chunk=[],size=0;
  const send=async()=>{if(!chunk.length)return;const r=await api('/api/admin/cases/stage',{method:'POST',body:JSON.stringify({format:data.format,documents:chunk})});staged+=r.staged;rejected+=r.rejected||0;skipped+=r.skippedExisting||0;notice.textContent=`${staged.toLocaleString('ko-KR')}건 검토 대기로 올림 · 이미 공개 ${skipped}건 · 형식 불일치 ${rejected}건`;chunk=[];size=0};
  for(const doc of data.documents){const bytes=JSON.stringify(doc).length*3;if(size+bytes>1400000||chunk.length>=500)await send();chunk.push(doc);size+=bytes}
  await send();toast('수집 파일을 검토 대기로 올렸습니다.');loadCasePending();
 }catch(error){notice.textContent=error.message}
}
function bindLawConnection(){
 loadCasePending();loadLawPending();
 if($('#runCaseBackfill'))$('#runCaseBackfill').onclick=runCaseBackfill;
 if($('#stopCaseBackfill'))$('#stopCaseBackfill').onclick=()=>{if(state.caseRun)state.caseRun.stop=true;$('#caseUpdateNotice').textContent+=' · 현재 페이지까지 저장 후 멈춥니다.'};
 if($('#lawFile'))$('#lawFile').onchange=e=>{const file=e.target.files[0];if(file)uploadLawFile(file);e.target.value=''};
 if($('#caseFile'))$('#caseFile').onchange=e=>{const file=e.target.files[0];if(file)uploadCaseFile(file);e.target.value=''};
 if($('#checkHolidays'))$('#checkHolidays').onclick=async()=>{try{const r=await api('/api/admin/holidays');$('#holidayList').innerHTML=!r.configured?'<p class="source-caption">HOLIDAY_API_KEY가 등록되지 않았습니다.</p>':r.error?`<p class="source-caption">${esc(r.error)}</p>`:`<p class="source-caption">오늘(${esc(r.date)}) ${r.holiday?'공휴일: '+esc(r.name):'공휴일 아님'} · ${r.holidays.map(h=>esc(h.date.slice(5).replace('-','.'))+' '+esc(h.name)).join(', ')}</p>`}catch(e){toast(e.message)}};
 if($('#lawConnectionForm'))$('#lawConnectionForm').onsubmit=async e=>{e.preventDefault();const oc=$('#lawApiOc').value;$('#lawApiOc').value='';try{const result=await api('/api/admin/law-connection',{method:'POST',body:JSON.stringify({oc,registrationConfirmed:$('#lawOcApproved').checked})});toast(result.message);await refreshData();renderAdmin()}catch(error){$('#lawConnectionNotice').innerHTML='<div class="notice warn">'+esc(error.message)+'</div>'}};
 if($('#removeLawConnection'))$('#removeLawConnection').onclick=async()=>{try{await api('/api/admin/law-connection',{method:'DELETE'});await refreshData();renderAdmin()}catch(e){toast(e.message)}};
 const runLaws=force=>async e=>{
  if(force&&!confirm('앱에 있는 모든 법령의 현재 버전 본문을 공식 API에서 다시 받아 검토 대기에 올립니다. 공개는 검토 후 직접 진행합니다.'))return;
  e.target.disabled=true;const notice=$('#lawConnectionNotice');let batch=0,staged=0,unchanged=0,errors=[];
  try{while(batch!==null){notice.textContent=`공식 API에서 법령 현행 버전을 확인하고 있습니다 (${batch+1}번째 묶음)`;const r=await api('/api/admin/updates/run',{method:'POST',body:JSON.stringify({batch,...(force?{force:true}:{})})});if(r.state==='blocked'||r.state==='failed'&&!r.staged){notice.textContent=r.reason||r.message;break}staged+=(r.staged||[]).length;unchanged+=(r.unchanged||[]).length;errors.push(...(r.errors||[]));batch=r.nextBatch??null}
   if(batch===null){toast(`검토 대기 ${staged}건 추가 · 변경 없음 ${unchanged}건${errors.length?` · 실패 ${errors.length}건`:''}`);await refreshData();renderAdmin()}else e.target.disabled=false}
  catch(error){toast(error.message);e.target.disabled=false}};
 if($('#runLawUpdate'))$('#runLawUpdate').onclick=runLaws(false);
 if($('#forceLawUpdate'))$('#forceLawUpdate').onclick=runLaws(true);
}

